#!/bin/sh
# SPDX-License-Identifier: CERN-OHL-W-2.0
# Changed ROM words of the shipping-default image (generator defaults) at the
# head against base and against cbccf22, each generated by its own revision.
set -eu
. "$(dirname "$0")/env.sh"
w=$SCRATCH/wordiff; rm -rf "$w"; mkdir -p "$w"
for r in "$BASE_SHA" "$PREV_SHA" "$HEAD_SHA"; do
  git -C "$CLONE" show "$r:hdl/ucode/gen_gptp_ucode.py" > "$w/gen_$r.py"
  python3 "$w/gen_$r.py" -o "$w/$r.hex" | head -1
done
for r in "$BASE_SHA" "$PREV_SHA"; do
  n=$(paste -d' ' "$w/$r.hex" "$w/$HEAD_SHA.hex" | awk '$1!=$2' | wc -l)
  echo "changed words, $r -> head: $n"
done
